


CREATE TABLE demographics(pid VARCHAR, responses INTEGER, logins INTEGER, first_login TIMESTAMP, last_login TIMESTAMP, country VARCHAR, age INTEGER, gender VARCHAR, n_demographics INTEGER);
CREATE TABLE study_prompt_answered(pid VARCHAR, "EventName" VARCHAR, "Time" TIMESTAMP, "Time_utc" TIMESTAMP, "CampaignProgressionAmount" DOUBLE PRECISION, "CurrentGameMode" VARCHAR, "CurrentJobName" VARCHAR, "CurrentSessionLength" INTEGER, "LastSubtaskCompleted" VARCHAR, "LastTaskCompleted" VARCHAR, "LevelProgressionAmount" DOUBLE PRECISION, "LastStudyPromptType" VARCHAR, response DOUBLE PRECISION);
CREATE TABLE mood_reported(pid VARCHAR, "EventName" VARCHAR, "Time" TIMESTAMP, "Time_utc" TIMESTAMP, "CampaignProgressionAmount" DOUBLE PRECISION, "CurrentGameMode" VARCHAR, "CurrentJobName" VARCHAR, "CurrentSessionLength" INTEGER, "LastSubtaskCompleted" VARCHAR, "LastTaskCompleted" VARCHAR, "LevelProgressionAmount" DOUBLE PRECISION, "LastStudyPromptType" VARCHAR, response DOUBLE PRECISION);
CREATE TABLE player_logged_in(pid VARCHAR, "EventName" VARCHAR, "Time" TIMESTAMP, "Time_utc" TIMESTAMP);
CREATE TABLE game_saved(pid VARCHAR, "EventName" VARCHAR, "Time" TIMESTAMP, "Time_utc" TIMESTAMP, "CampaignProgressionAmount" DOUBLE PRECISION, "CrouchState" VARCHAR, "CumulativeTimeSpentInLevel" VARCHAR, "CurrentCreditAmount" DOUBLE PRECISION, "CurrentExtension" VARCHAR, "CurrentGameMode" VARCHAR, "CurrentJobName" VARCHAR, "CurrentNozzle" VARCHAR, "CurrentPosition" VARCHAR, "CurrentSessionLength" INTEGER, "CurrentWasher" VARCHAR, "LastTaskCompleted" VARCHAR, "LevelProgressionAmount" DOUBLE PRECISION);
CREATE TABLE study_reward_claimed(pid VARCHAR, "EventName" VARCHAR, "Time" TIMESTAMP, "Time_utc" TIMESTAMP, "CampaignProgressionAmount" DOUBLE PRECISION, "CurrentGameMode" VARCHAR, "CurrentJobName" VARCHAR, "CurrentSessionLength" INTEGER, "LastStudyPromptType" VARCHAR, "LastSubtaskCompleted" VARCHAR, "LastTaskCompleted" VARCHAR, "LevelProgressionAmount" DOUBLE PRECISION, "RewardId" VARCHAR);
CREATE TABLE study_reward_unlocked(pid VARCHAR, "EventName" VARCHAR, "Time" TIMESTAMP, "Time_utc" TIMESTAMP, "CampaignProgressionAmount" DOUBLE PRECISION, "CurrentGameMode" VARCHAR, "CurrentJobName" VARCHAR, "CurrentSessionLength" INTEGER, "LastStudyPromptType" VARCHAR, "LastSubtaskCompleted" VARCHAR, "LastTaskCompleted" VARCHAR, "LevelProgressionAmount" DOUBLE PRECISION, "RewardId" VARCHAR);
CREATE TABLE update_current_state(pid VARCHAR, "EventName" VARCHAR, "Time" TIMESTAMP, "Time_utc" TIMESTAMP, "CampaignProgressionAmount" DOUBLE PRECISION, "CrouchState" VARCHAR, "CumulativeTimeSpentInLevel" VARCHAR, "CurrentCreditAmount" DOUBLE PRECISION, "CurrentExtension" VARCHAR, "CurrentNozzle" VARCHAR, "CurrentPosition" VARCHAR, "CurrentSessionLength" INTEGER, "CurrentWasher" VARCHAR, "IsIdleInGame" BOOLEAN, "IsInMenu" BOOLEAN, "LevelProgressionAmount" DOUBLE PRECISION);
