CREATE TABLE task_completed(pid VARCHAR, "EventName" VARCHAR, "Time" TIMESTAMP, "Time_utc" TIMESTAMP, "CrouchState" VARCHAR, "CurrentExtension" VARCHAR, "CurrentGameMode" VARCHAR, "CurrentNozzle" VARCHAR, "CurrentPosition" VARCHAR, "CurrentWasher" VARCHAR, "LastSubtaskCompleted" VARCHAR, "LastTaskCompleted" VARCHAR, "LevelProgressionAmount" DOUBLE PRECISION);
