CREATE TABLE exited_game(pid VARCHAR, "EventName" VARCHAR, "Time" TIMESTAMP, "Time_utc" TIMESTAMP, "CampaignProgressionAmount" DOUBLE PRECISION, "CurrentCreditAmount" DOUBLE PRECISION, "CurrentGameMode" VARCHAR, "CurrentJobName" VARCHAR, "CurrentSessionLength" INTEGER, "LevelProgressionAmount" DOUBLE PRECISION);